#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
// Tiled kernel: CTA-level spatial tiling with shared-memory staging of the
// reusable input patch (halo included). Each block computes an
// OH_TILE x OW_TILE output tile for CcPerBlock channels; the corresponding
// input patch is loaded once into shared memory and reused by every tap and
// every output row of the tile instead of being re-read from global memory.
// Asynchronous global->shared staging (cp.async, sm_80+). The float4 input
// tile loads are moved straight into shared memory without round-tripping
// through registers. For this DRAM-bound kernel (92% DRAM throughput)
// whose theoretical occupancy (66.7%) is capped by its ~63 registers per
// thread, eliminating the LDG->STS register round-trip in the staging loop
// cuts live register state so more CTAs stay resident per SM and more DRAM
// requests remain in flight.
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
#define DWCONV2D_HAS_CP_ASYNC 1
#endif
__device__ __forceinline__ void cp_async_16(void* smem_dst, const void* gmem_src) {
#if defined(DWCONV2D_HAS_CP_ASYNC)
  unsigned dst = (unsigned)__cvta_generic_to_shared(smem_dst);
  asm volatile("cp.async.ca.shared.global [%0], [%1], 16;\n" :: "r"(dst), "l"(gmem_src));
#endif
}
__device__ __forceinline__ void cp_async_wait_all() {
#if defined(DWCONV2D_HAS_CP_ASYNC)
  asm volatile("cp.async.commit_group;\n" ::);
  asm volatile("cp.async.wait_group 0;\n" ::);
#endif
